                    f"Loss_Curve_Activation_{activation_name}_Size_{hidden_layer_size}.png",
                )
            )
            plt.close()
        except Exception as e:
            print(
                f"Error creating loss plot for {activation_name}, size {hidden_layer_size}: {e}"
            )
            plt.close()

